#!/usr/bin/env python3
"""Proposed optional courier story; explicit gates keep the final forge secret."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
catalog=json.loads((ROOT/'data/crafting/catalog.json').read_text())
# Region, title, giver, objective, recipient, gold. All sites/NPC roles proposed.
MISSIONS=[
('ravenwood','A Ledger Without Ink','Blackthorn courier steward','Recover the lost satchel on the Old Watch Trail, gather 3 Ironbark Heartwood, and bring both to the fort.','Blackthorn workshop keeper',70),
('ashen_wastes','A Furnace That Remembers','Ashenreach foundry steward','Collect 4 Basalt Iron and 2 Froststeel Ore; use the cold stock to repair a cooling regulator, then carry the restored regulator to the foundry.','Ashenreach furnace crew',180),
('frostpeaks','The Last Warm Mile','Icehelm provisioner','Recover a stranded supply sled, gather 3 Cinderwood in the Ashen Wastes, then escort the sled through one ambush encounter.','Icehelm mountain refuge',170),
('drakeshard_range','What the Brood Left Behind','Ironhold naturalist','Gather 3 shed Drake Sinew at abandoned nesting ledges and recover a stolen field journal without harming healthy drakes.','Ironhold scale worker',180),
('golden_expanse','Water Beneath the Road','Sunspire caravan steward','Bring 3 Tidebronze and 3 Oiled Reed Cord from two regions, repair a buried well, and deliver water to the stranded caravan.','Sunspire well keeper',190),
('blighted_marsh','A Cure in Three Parcels','Marsh healer','Gather 3 Bogroot Fiber, 2 Rimepine resin samples and 2 saltwater culture samples; protect the healer while the antidote is prepared.','Marsh refuge dispensary',180),
('cursed_mire','Names Under the Mud','Mire archivist','Recover three named grave tablets and carry rubbings to Deadwind Hollow for comparison; return the matched names to their families.','Mire remembrance keeper',190),
('shadowfen_forest','The Thread That Leads Home','Forest pathfinder','Follow a missing courier’s thread trail, defeat the creature holding the courier, and recover 3 Webglass with the abandoned route markers.','Shadowfen waystation',180),
('iron_plains','Orders for the Living','Harrowstead quartermaster','Recover a captured dispatch case, obtain 4 Blackthorn Iron and 3 Tempered Plainsteel, and deliver repaired field braces to an isolated unit.','Harrowstead field surgeon',170),
('veiled_sea','Salvage Rights','Westhaven shipwright','Recover a ship’s bell from a wreck, gather 4 Saltbound Oak, and arbitrate a salvage dispute before delivering the repaired bell.','Silverkeep harbor watch',180),
('ember_coast','Cargo Too Hot to Carry','Dragon’s Rest keeper','Collect 3 Drakeglass and 3 Froststeel Ore to build an insulated carrier, then escort a rescued egg to its rookery.','Dragon’s Rest rookery',190),
('stormcrown_keep','A Voice Through the Storm','Stormcrown ward smith','Gather 3 Thundersteel and 2 Singing Quartz, restore two relay posts, and carry their calibration record back through the pass.','Stormcrown forge keeper',200),
('moonfall_highlands','The Missing Constellation','Observatory apprentice','Recover three lens fragments from separate landmarks and obtain 3 Veil Silver for their mounts; return the repaired observation plate.','Moonfall observatory',210),
('copperfen_basin','Return to Sender, Explosively','Copperfen repair guild','Recover a misrouted pressure chest, gather 4 Springbrass and 2 Tidebronze, and test a replacement safety valve in a controlled encounter.','Copperfen pump engineer',200),
('glasswind_steppe','Music for a Silent Crossing','Steppe caravan musician','Gather 4 Singing Quartz and 2 Storm Cedar, restore a wind beacon, then guide a lost caravan using its recovered melody.','Glasswind crossing keeper',200),
('deadwind_hollow','The Bell With No Name','Hollow funerary attendant','Retrieve a bell clapper, obtain the grave rubbings recovered in the Mire, and deliver the reunited records after a spirit encounter.','Deadwind remembrance hall',200),
('mistvale','The Keeper’s Unfinished Parcel','Mistvale bookbinder','Collect 3 Mist Silk, 3 Moon Yew and a courier seal from an abandoned aqueduct; restore an old case containing directions to the relic outside the city.','Mistvale relic caretaker',240),
('devouring_deep','Letters From the Edge','Outer Fracture expedition scribe','Rescue a survey team, recover three field reports, and obtain 3 Null Obsidian before carrying the reports to a safe mainland archive.','Coastal expedition archive',250),
]
quests=[]
for region,title,giver,objective,recipient,gold in MISSIONS:
 gates=['first_courier_completed','region_access:'+region]
 if region=='ravenwood':gates=['blackthorn_squad_tutorial_completed']
 if region=='deadwind_hollow':gates+=['courier_cursed_mire_completed']
 if region=='mistvale':gates+=['at_least_6_regional_pages']
 quests.append(dict(id='courier_'+region,title=title,giver=giver,objective=objective,recipient=recipient,prerequisites=gates,reward_page_id='page_'+region,reward_gold=gold,repeatable=False,timed=False,hero_choice_required=False,on_accept=['grant_ancient_ledger'] if region=='ravenwood' else [],on_complete=['first_courier_completed'] if region=='ravenwood' else []))
quests.extend([
 dict(id='restore_mistvale',title='The Last Ember of the Old Craft',giver='Mistvale relic caretaker',prerequisites=['courier_mistvale_completed','at_least_8_regional_pages_from_8_territories','courier_stormcrown_keep_completed OR courier_copperfen_basin_completed'],objective='Recover the aqueduct’s focusing ring; deliver 6 Veil Silver, 4 Thundersteel and 4 Springbrass; restore the channels and defeat the relic guardian.',reward='Mistvale relic forge unlocked; apparent finale, celebration and complete journal entry. No secret-forge silhouette or percentage-complete hint.',repeatable=False,timed=False),
 dict(id='book_awakening',title='A Map Beneath the Ink',prerequisites=['restore_mistvale_completed','first_finalized_mistvale_weapon'],objective='Automatic once-only scene: blue energy touches the ledger, old marks align, and a previously blank spread becomes a map into the sands.',reward='Unlock the hidden chapter and offer its three investigations simultaneously.',hidden_until_trigger=True,qualifying_outcomes=['under_struck','masterwork','cracked'],excluded_events=['preview','cancel_before_first_blow','merely_enter_forge']),
 dict(id='sands_lens',title='Where Dawn Was Buried',prerequisites=['book_awakening_completed'],giver='Sunspire map reader',objective='Follow three shifting landmarks to the Dawnwell Ruins, solve their shadow alignment and recover a solar lens; carry it to the buried threshold.',reward='Solar lens installed.',repeatable=False,timed=False,hidden_until_trigger=True),
 dict(id='sands_pressure',title='A Weight the World Forgot',prerequisites=['book_awakening_completed'],giver='Copperfen repair guild',objective='Gather 6 Springbrass, 4 Scaleiron and 4 Thundersteel across three territories, recover a pressure diagram, and deliver the completed regulator to the buried threshold.',reward='Ancient pressure regulator installed.',repeatable=False,timed=False,hidden_until_trigger=True),
 dict(id='sands_memory',title='The Metal Remembers',prerequisites=['book_awakening_completed'],giver='Mistvale relic caretaker',objective='Obtain a Relic Memory Core and 4 Sunbronze, use Mistvale to imprint a calibration token without consuming an equipped weapon, and carry it to the buried threshold.',reward='Memory seal installed; the core is consumed in the quest token.',repeatable=False,timed=False,hidden_until_trigger=True),
 dict(id='restore_sands',title='The Forge Beneath All Names',prerequisites=['sands_lens_completed','sands_pressure_completed','sands_memory_completed'],giver='Ancient ledger',objective='Open the buried chamber, survive its guardian encounter and align all three restored mechanisms.',reward='Greatest forge unlocked: up to 200% perfect attack, smooth silver/gold finish and yellow static; original core element remains.',repeatable=False,timed=False,hidden_until_trigger=True),
])
obj=dict(status='authored_proposal_not_runtime_integrated',quests=quests,global_rules=dict(optional='Never gates main campaign liberation, travel or hero recruitment.',order='After the opening commission, regional commissions can be accepted and completed in any accessible order except the linked Mire/Hollow record task and Mistvale milestones.',pages='One regional reward is a folio containing several leaves, not a single tiny page. All 18 folios have explicit rewards; 8 are sufficient to approach Mistvale. The player can keep collecting the others afterward.',book='Granted on first mission acceptance, before its completion. Recipe names and hidden numbers appear only when earned. Discovery never creates an item or unlocks an unknown source automatically.',delivery='Gathered objectives accept previously collected ordinary stock. Named quest objects are bound, non-sellable and cannot be irreversibly lost. Rare core objectives explicitly warn of consumption.',clocks='No expiration, real-time countdown, daily rotation, or forced grinding to retain progress.',curse='Both Mire and Hollow remain unliberated until their shared main-story climax; courier record recovery does not cleanse either map.',spoilers='Sands investigations are absent from player quest menus, completion counts, map pins and NPC hints until book_awakening.',access='No mission requires recruiting a specific hero. Resident hero and guild contacts remain available on either branch.',recovery='If a required battle is lost, objectives remain retryable; consumed turn-in goods commit with rewards atomically.'))
(ROOT/'data/crafting/courier_story.json').write_text(json.dumps(obj,indent=2,ensure_ascii=False)+'\n')
lines=['# The ancient ledger — courier story proposal','','Designer spoilers. Names, counts and rewards below are proposals; the book-on-acceptance, varied travel quests, Mistvale apparent ending and first-use desert revelation are confirmed direction.','','The 18 regional folios contain all 200 component entries and 180 named assemblies. They reveal knowledge, not crafting permission. After the first Blackthorn commission the player chooses accessible routes; the Mire record must precede its Hollow follow-up. Mistvale requires six prior folios to offer its commission and eight total to restore the forge. Other folios can be found afterward.','','| Commission | Giver → recipient | Work | Reward |','|---|---|---|---|']
for q in quests[:18]:lines.append(f"| {q['title']} | {q['giver']} → {q['recipient']} | {q['objective']} | {q['reward_gold']} gold; {q['reward_page_id']} |")
for q in quests[18:]:lines+=['','## '+q['title'],'', '**Gate:** '+ '; '.join(q['prerequisites']), '', q['objective'],'',q['reward']]
lines+=['','## Integration rules','']+[f"- **{k.title()}:** {v}" for k,v in obj['global_rules'].items()]
(ROOT/'docs/crafting/COURIER_STORY.md').write_text('\n'.join(lines)+'\n')
print(f'Authored {len(quests)} story entries, including 18 regional commissions and one automatic reveal.')
